                    : classroot.dir == "right" ? -Math.PI / 2 : 0 },

    draw(d: Draw) {
        d.scale(this.unit, this.unit)
        d.strokeStyle = this.ink
        d.lineWidth = this.weight / this.unit
        d.lineCap = "round"
        d.lineJoin = "round"
        d.save()
        d.translate(8, 8)
        d.rotate(this.angle)
        d.beginPath()
        d.moveTo(-3.5, -1.75)
        d.lineTo(0, 1.75)
        d.lineTo(3.5, -1.75)
        d.stroke()
        d.restore()
        }
    ]


